insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-coord-and-keep-going-sam-2026-11-22','decision','Sam: /coord and keep the queue going beside his new session','Sam, 2026-11-22 about 11:03Z, live in S703: "/coord and keep going. I will be starting another session but don''t let that stop the queue." The 10:12Z firing had stood down while S701 was live. S703 ran as the routine''s conductor beside his plain session S702, one writer per file. A decision for that night; it adds no standing ruling.',array['conductor','queue','sessions','sam-ruling'],'verified','Sam live in session S703, 2026-11-22; docs/session_704_handoff.md','Sam',now(),'SkyDovekie (S703)',date '2026-11-22'),
('d-glendale-own-pages-filed-as-gaps-s703','decision','Glendale''s 11 with no record file are filed as named gaps','S703 conductor: Glendale''s 11 programs with no record file read not_found with no text, so only= refuses them before any model call; six have an own page of low coverage and five none. No change to the shared _ranked or candidates code; the 11 are filed as named gaps (#3675) and the data-names-the-program lever goes to the next follow-up.',array['program-requirements','glendale','named-gaps'],'proposed','#3675','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-glendale-obt-stv-prefix-alias-s703','decision','Glendale 38973: OBT printed as STV is a per-college prefix alias','S703 conductor: Glendale 38973''s state list is a re-prefix, OBT printed as STV in the catalog. A per-college alias in Glendale''s reconcile entry binds them (#3675). Its staged read was refused by p-sources-from-repays-refused-pages-s689, so it took a fresh read (45030485543).',array['program-requirements','glendale','prefix-alias'],'proposed','#3675','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-ge-gap-only-where-no-figure-s703','decision','ge_units_not_read applies only where no GE figure is printed','S703 conductor, after #3678''s second read: 21 of 152 records print a general education figure, which the free ge_units_steps lever passes, so they are held by key. The gap applies only where the notes say no units are printed, or are silent and the page shows none; a precision count is committed. Applied: 131 rows at 29 colleges.',array['program-requirements','named-gaps','general-education'],'proposed','#3678; supabase-migrate 45019924640','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-hours-gaps-hold-misreads-s703','decision','The hours gaps hold 19 records a reread, reconcile or person settles','S703 conductor, after #3679''s second read: held by key are eight a reread or reconcile wording passes free (Laney, De Anza, Mendocino, Coastline), ten hours_total_not_read records read without the program section, and Reedley 42457 as a rounding question. Applied: 50 rows at 11 colleges (32 not read, 11 differs, 7 within a range).',array['program-requirements','named-gaps','noncredit-hours'],'proposed','#3679; supabase-migrate 45023631381','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-ccsf-gate-refresh-by-free-trial-s703','decision','City College of San Francisco''s recall gate is refreshed by a free trial','S703 conductor: CCSF''s outline recall gate on main named a stale parser, and the old trial saved no pages, so code could not refresh it. A free 12-page trial on main''s parser (45018845370) and a recount by hand: 12 of 12 on parser 2629a09a, no staff name filed. It rode #3677; the college''s next read can run.',array['course-outcomes','ccsf','recall-gate'],'proposed','#3677; #3676','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-clovis-through-pin-to-followup-s703','decision','Clovis 33432 and 33492 wait on a through pin field in the follow-up','S703 conductor: Clovis Entrepreneur 33432 and Social Science 33492 could not be pinned (the pin''s title check refuses 33432''s core page; 33492''s total prints past its window). A through pin field is a shared reader change, so it went to the night''s one follow-up (#3683). There 33492 passes; 33432 reads at coverage 0.933 with no total.',array['program-requirements','clovis','pins'],'proposed','#3681; #3683','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-clovis-management-is-the-standalone-degree-s703','decision','Clovis Management 33487 is the standalone degree','S703 conductor: Clovis''s Management program 33487 is pinned to the standalone degree''s page (p.109), never an option under General Business 33433 (p.106), which prints its own options and no major total. 33487 passes at the reread.',array['program-requirements','clovis','pins'],'proposed','#3681','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-clovis-two-gaps-existing-rules-s703','decision','Clovis 33433 and 33491 take the existing named gaps','S703 conductor: Clovis 33433 prints no degree total (core plus option) and 33491 prints 32-35 where its units sum to 33, so they take the existing total_not_printed and total_differs gaps without a new second read. Applied by supabase-migrate 45024254789, 2 of 2.',array['program-requirements','clovis','named-gaps'],'proposed','#3681; supabase-migrate 45024254789','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-legacy-objectives-kept-when-only-copy-s703','decision','A Legacy Data block''s objectives load when it is the only copy','S703 conductor, after #3677''s second read: the load''s first fix dropped HMID 535''s 11 real objectives, printed only under Legacy Data. A Legacy Data heading that opens a block now drops alone and its paragraph loads; after a block''s objectives it still ends the block. Across 144 filed reads only the two target rows change.',array['course-outcomes','sdcce','objectives'],'proposed','#3677','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-sdcce-load-objectives-only-s703','decision','San Diego College of Continuing Education loads objectives only','S703 conductor: SDCCE''s outline pages print a Student Learning Objectives field, one objective per entry, and no outcomes heading. Load 45021318423 filed 198 objective rows (1,860 objectives, 198 courses), confirmed live. Its 6 SLO rows read field labels; they go to the next follow-up, and the Commons shows them as outcomes until then.',array['course-outcomes','sdcce','objectives'],'proposed','#3677; load 45021318423','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-levers-paid-under-5-delegated-s703','decision','The levers worker dispatches paid reads up to $5 a college per run','S703 conductor: after free pricing, worker levers dispatches paid reads up to $5 a college per run without the conductor, within the $40 cap. Ohlone 2 loaded (45026280729, $0.14), San Joaquin Delta 6 (45029460149, $0.36); 141 programs at five colleges filed as named gaps in no_record_s703.json.',array['program-requirements','conductor','spend'],'proposed','#3686','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-lan-parse-parts-in-lan-fingerprint-only-s703','decision','Peralta''s parse parts sit in lan''s own parser fingerprint','S703 conductor: Peralta''s section parser and printed-college reading changed the outline reader, which would have moved the global fingerprint and staled every host''s recall gate. The fingerprint is per host: lan.curriqunet.com 27934ff7, the others 2629a09a, so no other college''s gate moved.',array['course-outcomes','peralta','recall-gate'],'proposed','#3684','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-lan-outcomes-only-host-s703','decision','lan.curriqunet.com is read as an outcomes-only host','S703 conductor: Peralta''s pages on lan.curriqunet.com carry staff fields beside the outcomes. The host is read outcomes-only, as City College of San Francisco''s is, so a filed page keeps the outcome sections and no staff field. Trial 45030224450 counted 11 of 12; full read 45031089800 (1,869 pages, 5 parts).',array['course-outcomes','peralta','privacy'],'proposed','#3684','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-lists-gap-holds-claim-false-s703','decision','lists_past_their_figure holds records whose note names the difference','S703 conductor, #3685''s second read: a record whose own note names the course, list or section that makes up the difference (would fit if, listed in error, may belong to List) is held by key; lists_claim learns the class. Six held in round one; 29 held in all. Applied: 17 rows at 9 colleges.',array['program-requirements','named-gaps','lists'],'proposed','#3685; supabase-migrate 45030559364','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-lists-gap-holds-range-sums-s703','decision','lists_past_their_figure holds sums inside a printed range','S703 conductor, #3685''s second read: six records whose sum sits inside the printed range (Gavilan 08460, 38787, 41394; Irvine Valley 32865; Palomar 33826; West Valley 32022) take no lists gap; lists_claim reads them as within_printed_range and the self-recall''s held answer follows.',array['program-requirements','named-gaps','lists'],'proposed','#3685','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('d-sjdelta-prefix-alias-stopgap-s703','decision','San Joaquin Delta''s apprenticeship programs bind by per-college prefix aliases','S703 conductor: six San Joaquin Delta apprenticeship programs bind to their pages through per-college prefix aliases IND, ELE and MEC with an A- prefix, a stopgap until the coarse net reads the hyphen (f-sjdelta-apprenticeship-coarse-net-s691; the next follow-up). Load 45029460149, $0.36.',array['program-requirements','san-joaquin-delta','prefix-alias'],'proposed','#3686','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('p-self-recall-reads-rule-fields-s703','pitfall','A self-recall whose held answer comes from the rule''s own fields measures nothing','S703: #3678 and #3679''s self-recalls read 1,685 and 3,297 right, 0 wrong, and the second reader still found 21 and 18 records the gap mislabeled, because each held answer came from the fields the rule reads. Add a claim check on the record''s notes, boundary readings and a precision count against hand-held records.',array['program-requirements','named-gaps','testing','self-recall'],'proposed','#3678; #3679; docs/kb-notes/methodology-a-test-must-not-take-its-rule-as-the-truth.md','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('p-sources-from-refuses-pinned-refused-s703','pitfall','A sources_from paid read refuses a pinned program refused before','S703: a sources_from paid read refuses a pinned program whose pages were refused before (Ohlone 45025818053), as p-sources-from-repays-refused-pages-s689 also refused Glendale 38973''s staged read. Read fresh. The pinned refusal goes to the next follow-up.',array['program-requirements','reader','paid-read'],'proposed','#3686; #3675','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('p-merge-head-push-starts-no-read-s703','pitfall','A push whose head is a merge commit starts no page read','S703: the read workflows skip a push whose head commit is a merge, so a branch that merged main and pushed started no page read. Dispatch the read by plan name instead of waiting on a push.',array['program-requirements','workflows','dispatch'],'proposed','docs/session_704_handoff.md','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('p-global-fingerprint-stales-every-gate-s703','pitfall','A reader change that moves the global parser fingerprint stales every host''s gate','S703: the outline recall gates bind to the parser''s fingerprint, so a reader change for one host (Peralta) would have staled every other host''s gate. Make the fingerprint per host (d-lan-parse-parts-in-lan-fingerprint-only-s703).',array['course-outcomes','recall-gate','reader'],'proposed','#3684','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('p-lan-not-outcomes-only-filed-names-s703','pitfall','A shape trial on a host not yet outcomes-only filed pages with a staff name','S703: Peralta''s 5-page shape trial filed pages that print an Originator''s name, because lan.curriqunet.com was not yet outcomes-only. One fresh commit and a force-with-lease on the claude/* branch scrubbed it; the 30-day artifact course-outcomes-45026998155-part1 still holds the pages, for a person to delete. No name goes in any document.',array['course-outcomes','privacy','peralta'],'proposed','#3684; docs/session_704_handoff.md','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('p-records-prs-merge-one-at-a-time-s703','pitfall','Records PRs merge one at a time, about 25 minutes of CI each','S703: every records PR rebuilds commons_data.json, so each merge sends the next records PR back to merge main, take main''s side of the Commons files and rerun both builders, a CI cycle of about 25 minutes. Plan the night''s merges one at a time, oldest finished first.',array['program-requirements','commons','merge'],'proposed','docs/session_704_handoff.md','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('p-test-check-after-lints-s703','pitfall','The test check appears only after lints finishes','S703: on a PR head the test check is created only after lints finishes, so a head showing no test yet is pending, never green. Wait for test itself to report success before a merge.',array['merge','ci','branch-policy'],'proposed','docs/session_704_handoff.md','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('f-followup-minors-left-s703','fact','The minors that wait for the next night''s follow-up','S703: SDCCE''s 6 SLO-label rows; Peralta''s 4 parse minors; Los Angeles Harbor 44271, LA Trade-Tech 44345 and 45670; Orange Coast 03997, 08668, 12159; the hours reconcile eight; Mt. San Antonio 43777 and 43999 (capture reach); Glendale''s data-names-the-program lever; the coarse-net hyphen; the sources_from pinned refusal; the through window''s until field.',array['program-requirements','follow-up'],'proposed','docs/session_704_handoff.md; docs/reference/lanes/program-requirements-harvest.md','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('m-collection-s703','milestone','S703''s collection: four named-gap applies, 200 rows; pins and levers','S703: named gaps applied ge_units_not_read 131 (#3678), hours 50 (#3679), Clovis 2 (#3681) and lists_past_their_figure 17 (#3685), 200 rows, 69 held by key. Pins at Cosumnes River and Clovis: 3 new, 4 replaced, 5 passing. In flight: Ohlone 2, San Joaquin Delta 6, Butte 1 and Clovis 33492 loaded; 141 plus Glendale''s 11 filed as gaps. $1.29 of extraction.',array['program-requirements','collection','named-gaps'],'proposed','#3678; #3679; #3681; #3685; #3686; #3675; #3683','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22'),
('m-sdcce-outlines-loaded-s703','milestone','San Diego College of Continuing Education''s outlines loaded: 198 rows','S703 (#3677 50e4bc1d): index 45016944119 (199 of 228 codes hold an outline), trial 45017581874 (12 of 12), full read 45018663453 (199 pages, all 200), load 45021318423: 198 objective rows holding 1,860 objectives at 198 courses, confirmed live. The receipt rides the checkpoint #3674.',array['course-outcomes','sdcce','objectives'],'proposed','#3677; load 45021318423','SkyDovekie (S703), the conductor',null,'SkyDovekie (S703)',date '2026-11-22')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
